using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.FNZ.TiposMovimiento;using GraphApi.Services.FNZ.TiposMovimiento;namespace GraphApi.Controllers.FNZ.TiposMovimiento{    /// <summary>    /// Gestión de TiposMovimientos: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("FNZ/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre TiposMovimientos")]    public class TiposMovimientoController : Controller    {        private readonly ITiposMovimientoService _objService;        public TiposMovimientoController(ITiposMovimientoService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los TiposMovimientos, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="tipoMovimientoID">TipoMovimientoID</param>        /// <param name="tipoMovimiento">TipoMovimiento</param>        /// <param name="bCargo">bCargo</param>        /// <param name="bAbono">bAbono</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de TiposMovimientos</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar TiposMovimientos",            Description = "Devuelve TiposMovimientos aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadTiposMovimiento>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadTiposMovimiento>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? tipoMovimientoID,            [FromQuery] string? tipoMovimiento,            [FromQuery] bool? bCargo,            [FromQuery] bool? bAbono,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetTiposMovimientosDynamic(                tipoMovimientoID,                 tipoMovimiento,                 bCargo,                 bAbono,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo TiposMovimiento.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del TiposMovimiento a crear.</param>        /// <returns>El TiposMovimiento recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear TiposMovimientos",            Description = "Inserta un nuevo TiposMovimiento en la base de datos."        )]        [ProducesResponseType(typeof(clReadTiposMovimiento), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadTiposMovimiento>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateTiposMovimiento objInput)        {            var vCreated = await _objService.CreateTiposMovimiento(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de TiposMovimiento.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del TiposMovimiento.</param>        /// <returns>El TiposMovimiento actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar TiposMovimientos",            Description = "Actualiza uno o varios campos de TiposMovimiento existente."        )]        [ProducesResponseType(typeof(clReadTiposMovimiento), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadTiposMovimiento>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateTiposMovimiento objInput)        {            var vUpdated = await _objService.UpdateTiposMovimiento(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un TiposMovimiento por su ID.        /// </summary>        [HttpDelete("{nTiposMovimientoID:int}")]        [SwaggerOperation(            Summary = "Eliminar TiposMovimiento",            Description = "Borra un TiposMovimiento si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nTiposMovimientoID)        {            var success = await _objService.DeleteTiposMovimiento(nTiposMovimientoID);            return success ? NoContent() : NotFound();        }    }}